<template><div class="dashboard"><div class="d-flex align-center flex-wrap mb-6"><div><div class="text-overline">ZEERAK REAL ESTATE & BUILDERS</div><h1 class="text-h4 font-weight-bold">Dashboard</h1><div class="grey--text">Sales, inventory and collection snapshot.</div></div><v-spacer/><v-btn color="#165134" dark depressed to="/admin/properties/create"><v-icon left>mdi-home-plus</v-icon>Add Property</v-btn></div><v-row><v-col v-for="stat in statistics" :key="stat.title" cols="12" sm="6" lg="3"><v-card flat class="stat pa-5"><div class="d-flex align-center"><v-avatar size="48" color="#165134"><v-icon dark>{{stat.icon}}</v-icon></v-avatar><div class="ml-4"><div class="text-caption grey--text">{{stat.title}}</div><div class="text-h6 font-weight-bold">{{stat.value}}</div></div></div></v-card></v-col></v-row><v-row class="mt-2"><v-col cols="12" lg="7"><v-card flat class="pa-5 fill-height"><div class="d-flex align-center mb-3"><div><div class="text-h6 font-weight-bold">Inventory</div><div class="text-caption grey--text">Current property pipeline</div></div><v-spacer/><v-btn text small to="/admin/properties">View inventory</v-btn></div><v-row><v-col v-for="item in propertyStatus" :key="item.title" cols="6" sm="3"><div class="inventory-box"><div class="text-h5 font-weight-bold">{{item.value}}</div><div class="text-caption grey--text">{{item.title}}</div></div></v-col></v-row></v-card></v-col><v-col cols="12" lg="5"><v-card flat class="pa-5 fill-height"><div class="text-h6 font-weight-bold mb-1">Collections</div><div class="text-caption grey--text">Payment activity and receivables</div><div class="metric-row mt-5"><span>Total collected</span><b>PKR {{format(collections)}}</b></div><div class="metric-row"><span>Outstanding</span><b class="error--text">PKR {{format(receivables)}}</b></div><div class="metric-row"><span>Overdue installments</span><b>{{overdue}}</b></div><v-btn block outlined color="#165134" class="mt-5" to="/admin/payments">Open collections</v-btn></v-card></v-col></v-row></div></template><script>import api from '../../services/api';export default{name:'Dashboard',data(){return{statistics:[{title:'Properties',value:'—',icon:'mdi-home-city'},{title:'Customers',value:'—',icon:'mdi-account-group'},{title:'Bookings',value:'—',icon:'mdi-bookmark-check'},{title:'Sales Value',value:'PKR —',icon:'mdi-cash-multiple'}],propertyStatus:[{title:'Available',value:0},{title:'Reserved',value:0},{title:'Booked',value:0},{title:'Sold',value:0}],collections:0,receivables:0,overdue:0}},mounted(){this.load()},methods:{async load(){try{const [p,c,b,pay,i]=await Promise.all([api.get('/properties/inventory'),api.get('/customers',{params:{per_page:1}}),api.get('/bookings',{params:{per_page:100}}),api.get('/payments',{params:{per_page:100}}),api.get('/installments',{params:{status:'overdue',per_page:100}})]);const inv=p.data||p.data.inventory||{};const propCount=Object.values(inv).reduce((a,v)=>a+(Number.isFinite(Number(v))?Number(v):0),0);this.propertyStatus=[{title:'Available',value:Number(inv.available||0)},{title:'Reserved',value:Number(inv.reserved||0)},{title:'Booked',value:Number(inv.booked||0)},{title:'Sold',value:Number(inv.sold||0)}];const bookings=b.data.data||[];this.collections=(pay.data.data||[]).reduce((s,x)=>s+Number(x.amount||0),0);this.receivables=bookings.reduce((s,x)=>s+Number(x.remaining_amount||0),0);this.overdue=(i.data.data||[]).length;this.statistics=[{title:'Properties',value:String(propCount),icon:'mdi-home-city'},{title:'Customers',value:String(c.data.total||0),icon:'mdi-account-group'},{title:'Bookings',value:String(b.data.total||bookings.length),icon:'mdi-bookmark-check'},{title:'Sales Value',value:'PKR '+this.format(bookings.reduce((s,x)=>s+Number(x.final_price||0),0)),icon:'mdi-cash-multiple'}]}catch(e){}},format(v){return new Intl.NumberFormat('en-PK',{maximumFractionDigits:0}).format(Number(v||0))}}}</script><style scoped>.stat,.fill-height{border:1px solid rgba(0,0,0,.06);border-radius:14px}.stat{transition:transform .2s}.stat:hover{transform:translateY(-2px)}.inventory-box{padding:18px;border-radius:12px;background:rgba(22,81,52,.05)}.metric-row{display:flex;justify-content:space-between;padding:14px 0;border-bottom:1px solid rgba(0,0,0,.08)}.dashboard{width:100%}</style>